// Review saved no-NOS races and current prices; no new simulations.
import fs from 'node:fs';
import {STOCK_CLASS_DATA} from '../src/data/stockClasses.js';
import {getAutoMarketBasePrice} from '../src/data/centralTokyo.js';
const rows=JSON.parse(fs.readFileSync('docs/engineering/revised.json'));
const stages=['stock','budget','street','intermediate','advanced','max'];
const stocks=rows.filter(r=>r.build==='stock'&&r.id!=='magna');
const f=n=>n.toFixed(2);
const lines=['# Classes and upgrade progression — gameplay review',
'Generated by `node tools/class-progression-review.mjs` from saved 120 Hz, seeded no-NOS races. These are simulated times, not road-test measurements. Prices are current on the engineering branch, not necessarily latest main. No core simulation is rerun.',
'## Decision: retain four classes provisionally',
'A–C have useful standing and rolling performance bands. Do not move cars solely to equalize class sizes or to match reputation. The R34 is B despite its prestige; its price reflects more than stock race pace. Class D has one significant unresolved outlier, XT. Do not manufacture extra power or slow other cars to conceal it.',
'| Class | Cars | Standing 400 m range | Rolling 400 m range | Two cheapest eligible models / donor yen |',
'|---|---:|---|---|---|'];
for(const cls of ['A','B','C','D']){
 const group=stocks.filter(r=>STOCK_CLASS_DATA[r.id].stockClass===cls);
 const range=mode=>[Math.min(...group.map(r=>r[mode].splits[400])),Math.max(...group.map(r=>r[mode].splits[400]))].map(f).join('–');
 const cheapest=[...group].sort((a,b)=>getAutoMarketBasePrice(a.id)-getAutoMarketBasePrice(b.id)).slice(0,2);
 lines.push(`| ${cls} | ${group.length} | ${range('standing')} s | ${range('rolling')} s | ${cheapest.map(r=>r.id+' / '+getAutoMarketBasePrice(r.id).toLocaleString('en-US')).join('; ')} |`);
}
lines.push('','Recruitment continues to require a truly stock car of the same fixed class on every difficulty. Tuning potential is irrelevant to eligibility. Multiple dealer choices exist in each class, but this table does not prove a new player can afford each invitation; career earnings/unlock testing remains necessary. Magna is excluded from accessible-choice counts.','',
'## Useful progression at the same hardware budgets',
'Each cell is kW / standing 400 m seconds. Hardware costs are cumulative, excluding the donor, NOS and specialist/dyno fees. The sampled bundles are not claimed to be the cheapest optimized builds.',
'| Car | Donor yen | '+stages.map(s=>{const r=rows.find(r=>r.build===s);return s+' / ¥'+r.cost.toLocaleString('en-US');}).join(' | ')+' |',
'|---|---:|'+stages.map(()=>'---').join('|')+'|');
for(const id of ['ae86','ek9','dc2','s2000','fc3s','rx7fd','evo6','r34','jza80','nsx','xt']){
 const build=s=>rows.find(r=>r.id===id&&r.build===s);
 lines.push('| '+id+' | '+getAutoMarketBasePrice(id).toLocaleString('en-US')+' | '+stages.map(s=>Math.round(build(s).powerKW)+' / '+f(build(s).standing.splits[400])).join(' | ')+' |');
}
lines.push('','## Decisions and implementation','',
'- Keep the existing engineering envelopes this pass: saved results show useful successive stages, and the previous runaway NA conversions are no longer evident in these representative builds. This is not a claim that every possible parts combination is optimal.',
'- Cheap lightweight builds remain relevant: AE86 street hardware costs ¥214,000 and reaches about 14.06 s, close to the slower stock A cars; intermediate hardware reaches about 12.73 s. This is a comparison across builds, not permission to use modifications in recruitment.',
'- Factory-turbo headroom remains meaningful: R34 and Supra exceed 400 kW at maximum standard hardware; the lighter DC2 remains competitive at about 311 kW without exceeding their absolute output.',
'- NSX remains a strong premium outlier, not artificially nerfed. Its ¥9m donor price and the saved human-driver/traction scenarios must remain part of endgame review. Neither cost nor this limited scenario set proves universal balance.',
'- Confirmed the active garage engine shop already uses the complete race build, including installed chassis/exhaust, calibration and specialist tuning. Added actionable boost-support advice that distinguishes an upgradeable component from one already at maximum level, plus preview-parity regressions for all 43 cars and specialist donors. No purchased modifications are changed.',
'- XT is the next targeted mechanical review: check its actual low-speed gearing, torque delivery and launch behaviour before changing a class or an engine envelope. A fifth class containing one car would not solve recruitment accessibility.',
'','## Remaining acceptance work','',
'Confirm XT behaviour with a bounded diagnostic; test invitation affordability along a non-dev career; reconcile newer main gameplay before an isolated playable preview. Existing source and browser results are not a deployment approval.');
fs.writeFileSync('docs/engineering/CLASS_PROGRESSION_REVIEW.md',lines.join('\n').replace(/^(#{1,2} .+)\n/gm,'$1\n\n').replace(/\n(## |\| Class |\| Car )/g,'\n\n$1')+'\n');
console.log('Reviewed four classes and six upgrade stages without rerunning races.');
